def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    env = observation.get("environment_name", "resource_collection")
    self_p = pos(observation.get("self_position"), (0, 0))
    opp_p = pos(observation.get("opponent_position"), self_p)

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_p, opp_p)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = corners[0]
        best = -1
        for c in corners:
            d = manhattan(c, opp_p)
            if d > best:
                best = d
                target = c
        return step_toward(self_p, target)

    if env == "territory_control":
        cells = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        best = None
        best_score = None
        for cell in cells:
            c = pos(cell)
            if c is None:
                continue
            score = manhattan(self_p, c)
            if observation.get("opponent_territory") and "opponent_territory" in observation and observation.get("opponent_territory") == cells:
                score += 1
            if best is None or score < best_score:
                best = c
                best_score = score
        if best is not None:
            return step_toward(self_p, best)
        return step_away(self_p, opp_p)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = None
        best_score = None
        for r in resources:
            rp = pos(r)
            if rp is None:
                continue
            score = manhattan(self_p, rp)
            if best is None or score < best_score:
                best = rp
                best_score = score
        if best is not None:
            return step_toward(self_p, best)

    # Denial / fallback: move toward opponent, but avoid zero-mobility if already overlapping.
    if self_p == opp_p:
        return [1, 0]
    return step_toward(self_p, opp_p)

